//! Model-free fixture generated by the real durable writer and native serializer.
use super::*;

#[test]
fn saved_work_state_fixture_uses_native_serialization() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("tui-work.json");
    let budget = WorkBudget::new("fixture task", 32, Some(path.clone()));
    budget
        .configure(BudgetPolicy {
            transport_repair_limit: 4,
            observer_reserved_requests: 8,
        })
        .unwrap();
    for role in ["coder", "observer", "coder"] {
        let request = budget.begin(role, &serde_json::json!({})).unwrap();
        request.status("completed");
    }
    assert!(budget
        .reject_transport("coder", 2, TransportRejection::NativeArguments)
        .unwrap());
    let saved: WorkState = serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
    assert_eq!(
        serde_json::to_value(&saved).unwrap(),
        serde_json::to_value(budget.snapshot()).unwrap()
    );
    assert_eq!(saved.task_requests(), 2);
    assert_eq!(saved.requests.len(), 3);
    let mut normalized = saved;
    // Only unstable identity and clocks are normalized; fields and types come
    // from the native writer. No inference request is made by this test.
    normalized.task_id = "native-fixture".into();
    normalized.started_at_ms = 1;
    for request in &mut normalized.requests {
        request.duration_ms = Some(0);
    }
    let value = serde_json::to_value(normalized).unwrap();
    if let Some(output) = std::env::var_os("SPIRAL_NATIVE_FIXTURE_OUT") {
        use std::io::Write;
        let mut file = std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(output)
            .unwrap();
        writeln!(file, "{}", serde_json::to_string_pretty(&value).unwrap()).unwrap();
    } else {
        let expected: Value = serde_json::from_str(include_str!(
            "../../benchmarks/self-dogfood-v2/coupled-status/native_work.json"
        ))
        .unwrap();
        assert_eq!(value, expected);
    }
}
